// Configuración del optimizador. Solo la persona responsable cambia objetivos y topes.
// cpl_objetivo = costo objetivo por lead (MXN). Mientras sea null, el agente solo reporta.
const simular = (() => { try { return $('Probar (simulación)').isExecuted; } catch (e) { return false; } })();
const ahora = $now.setZone('America/Mexico_City');
const MARCAS = {
  'marca-a': { nombre: 'Marca A', act: '__META_AD_ACCOUNT_A__', cpl_objetivo: null },
  'marca-b': { nombre: 'Marca B', act: '__META_AD_ACCOUNT_B__', cpl_objetivo: null },
};
const TOPE = 300; // MXN al día por campaña: el agente nunca propone más
const enc = s => encodeURIComponent(s);
const lote = act => JSON.stringify([
  { method: 'GET', name: 'conjuntos', relative_url: act + '/adsets?limit=200&fields=id,name,campaign_id,campaign{name,daily_budget},status,effective_status,daily_budget,learning_stage_info&effective_status=' + enc('["ACTIVE"]') },
  { method: 'GET', name: 'anuncios', relative_url: act + '/ads?limit=500&fields=id,adset_id,effective_status&effective_status=' + enc('["ACTIVE"]') },
  { method: 'GET', name: 'diario', relative_url: act + '/insights?level=adset&date_preset=last_7d&time_increment=1&limit=500&fields=adset_id,spend,impressions,clicks,actions' },
  { method: 'GET', name: 'semana', relative_url: act + '/insights?level=adset&date_preset=last_7d&limit=500&fields=adset_id,spend,impressions,reach,frequency,clicks,actions' },
]);
return [{ json: { simular, fecha: ahora.toFormat('yyyy-MM-dd'), hora: ahora.toFormat('yyyy-MM-dd HH:mm'), hace3: ahora.minus({ days: 3 }).toFormat('yyyy-MM-dd'), TOPE, MARCAS, lote_a: lote(MARCAS['marca-a'].act), lote_b: lote(MARCAS['marca-b'].act) } }];

// Reglas (ventana: últimos 7 días). Pausar solo lo hace solo en campañas creadas por el agente
// («[Agente] …»); en las demás lo propone. Subir presupuesto siempre es propuesta, con tope.
const C = $('Configuración').first().json;
const recientes = $('Decisiones recientes').all().map(i => i.json).filter(r => r && r.adset_id);
const num = v => Number(v) || 0;
const leadsDe = a => (a || []).filter(x => /lead/i.test(String(x.action_type || ''))).reduce((s, x) => Math.max(s, num(x.value)), 0);
const msg = x => (x && x.error && (x.error.error_user_msg || x.error.message)) || '';
const filas = [], errores = [], pausas = { 'marca-a': [], 'marca-b': [] };
let frenado = false;
for (const [marca, nodo] of [['marca-a', 'Meta A'], ['marca-b', 'Meta B']]) {
  const M = C.MARCAS[marca], obj = M.cpl_objetivo ? num(M.cpl_objetivo) : 0;
  let items = [];
  try { items = $(nodo).all().map(i => i.json || {}); } catch (e) { errores.push(M.nombre + ': no se leyó Meta'); continue; }
  if (items.length === 1 && items[0].error) { errores.push(M.nombre + ': ' + msg(items[0]).slice(0, 200)); continue; }
  const partes = {};
  ['conjuntos', 'anuncios', 'diario', 'semana'].forEach((k, i) => {
    const x = items[i] || {}; let body = {};
    try { body = JSON.parse(x.body || '{}'); } catch (e) {}
    if (Number(x.code) !== 200 || body.error) errores.push(M.nombre + ' (' + k + '): ' + (msg(body) || ('código ' + x.code)).slice(0, 200));
    partes[k] = body.data || [];
    // Límites de uso de la API: frenar al pasar el 75 %.
    (x.headers || []).forEach(h => {
      const n = String(h.name || '').toLowerCase();
      if (n === 'x-business-use-case-usage' || n === 'x-ad-account-usage' || n === 'x-app-usage') {
        const nums = (String(h.value || '').match(/"(call_count|total_cputime|total_time|acc_id_util_pct)"\s*:\s*([0-9.]+)/g) || []).map(s => num(s.split(':')[1]));
        if (nums.some(v => v > 75)) frenado = true;
      }
    });
  });
  const anunciosPor = {}; partes.anuncios.forEach(a => { anunciosPor[a.adset_id] = (anunciosPor[a.adset_id] || 0) + 1; });
  const semana = {}; partes.semana.forEach(r => { semana[r.adset_id] = r; });
  const diario = {}; partes.diario.forEach(r => { (diario[r.adset_id] = diario[r.adset_id] || []).push(r); });
  for (const s of partes.conjuntos) {
    const w = semana[s.id] || {}, dias = (diario[s.id] || []).sort((a, b) => String(a.date_start).localeCompare(String(b.date_start)));
    const gasto = num(w.spend), leads = leadsDe(w.actions), cpl = leads ? gasto / leads : null, frec = num(w.frequency);
    const ult3 = dias.slice(-3), prev = dias.slice(0, -3);
    const sum = (arr, f) => arr.reduce((t, r) => t + f(r), 0);
    const ctr = arr => { const imp = sum(arr, r => num(r.impressions)); return imp ? sum(arr, r => num(r.clicks)) / imp : null; };
    const ctr3 = ctr(ult3), ctrPrev = ctr(prev), imPrev = sum(prev, r => num(r.impressions));
    const gasto3 = sum(ult3, r => num(r.spend)), leads3 = sum(ult3, r => leadsDe(r.actions));
    const camp = (s.campaign && s.campaign.name) || '';
    const presupuesto = num(s.daily_budget || (s.campaign && s.campaign.daily_budget)) / 100;
    const deAgente = /^\[Agente\]/.test(camp);
    const aprendiendo = String((s.learning_stage_info || {}).status || '').toUpperCase() === 'LEARNING';
    const base = { fecha: C.hora, marca, campana: camp.slice(0, 120), conjunto: String(s.name || '').slice(0, 120), adset_id: s.id, gasto_7d: Math.round(gasto * 100) / 100, leads_7d: leads, cpl_7d: cpl === null ? null : Math.round(cpl * 100) / 100, cpl_objetivo: obj || null, frecuencia: Math.round(frec * 100) / 100, presupuesto_dia: presupuesto || null, propuesta_presupuesto: null };
    const add = (regla, accion, estado, detalle, extra) => filas.push(Object.assign({}, base, { regla, accion, estado, detalle: String(detalle).slice(0, 500) }, extra || {}));
    const pausar = (regla, detalle) => {
      if (deAgente && !frenado) { pausas[marca].push(s.id); add(regla, 'pausar', C.simular ? 'simulación' : 'aplicada', detalle); }
      else add(regla, 'pausar', 'propuesta', detalle + (deAgente ? ' (no se aplicó: la API pasó el 75 % de uso)' : ' (campaña hecha a mano: solo propongo)'));
    };
    if (obj && leads === 0 && gasto >= 3 * obj) { pausar('desastre', 'Gastó MXN ' + gasto.toFixed(0) + ' en 7 días sin leads (3× el objetivo de ' + obj + ').'); continue; }
    if (aprendiendo) { if (gasto > 0) add('aprendizaje', 'no tocar', 'informativa', 'En fase de aprendizaje: no se toca.'); continue; }
    if (!obj) { if (gasto > 0) add('sin objetivo', 'solo reporte', 'informativa', 'Sin costo objetivo por lead: solo reporto. Gasto 7 d MXN ' + gasto.toFixed(0) + ', leads ' + leads + '.'); }
    else if (leads === 0 && gasto >= 2 * obj) { pausar('2× sin leads', 'Gastó MXN ' + gasto.toFixed(0) + ' sin leads (objetivo ' + obj + ').'); continue; }
    else if (cpl !== null && cpl > 1.5 * obj && (leads >= 5 || gasto >= 5 * obj)) { pausar('costo alto', 'Costo por lead MXN ' + cpl.toFixed(0) + ', más de 1.5× el objetivo (' + obj + ').'); continue; }
    else if (leads3 >= 3 && gasto3 / leads3 <= 0.8 * obj && presupuesto) {
      const subidaReciente = recientes.some(r => r.adset_id === s.id && r.regla === 'costo bajo' && String(r.fecha).slice(0, 10) >= C.hace3);
      const nuevo = Math.min(C.TOPE, Math.round(presupuesto * 1.15));
      if (!subidaReciente && nuevo > presupuesto) add('costo bajo', 'subir presupuesto', 'propuesta', 'Costo por lead de los últimos 3 días MXN ' + (gasto3 / leads3).toFixed(0) + ' (20 % o más abajo del objetivo ' + obj + '). Propongo pasar de MXN ' + presupuesto + ' a ' + nuevo + ' al día.', { propuesta_presupuesto: nuevo });
    }
    if (gasto <= 0) continue;
    if (frec > 3 && ctr3 !== null && ctrPrev !== null && imPrev >= 1000 && ctr3 < 0.8 * ctrPrev) add('fatiga', 'pedir creativos', 'propuesta', 'Frecuencia ' + frec.toFixed(1) + ' y CTR bajando (' + (ctrPrev * 100).toFixed(2) + ' % → ' + (ctr3 * 100).toFixed(2) + ' %).');
    if ((anunciosPor[s.id] || 0) < 2) add('pocos anuncios', 'proponer variantes', 'propuesta', 'Tiene ' + (anunciosPor[s.id] || 0) + ' anuncio(s) activo(s); conviene tener al menos 2.');
  }
}
const lote = ids => ids.length ? JSON.stringify(ids.map(id => ({ method: 'POST', relative_url: id, body: 'status=PAUSED' }))) : '';
const nombre = m => C.MARCAS[m].nombre;
const lineas = filas.filter(f => f.estado !== 'informativa').map(f => '• ' + nombre(f.marca) + ' · ' + f.conjunto + ': ' + f.accion + ' (' + f.estado + '). ' + f.detalle);
const sinObj = Object.keys(C.MARCAS).filter(m => !C.MARCAS[m].cpl_objetivo).map(nombre);
let mensaje = '';
if (lineas.length || errores.length) {
  mensaje = '<b>Meta Ads · optimizador</b>' + (C.simular ? ' (simulación)' : '') + '\n' + lineas.join('\n');
  if (errores.length) mensaje += '\n⚠️ ' + errores.join(' · ');
  if (frenado) mensaje += '\nFrené: la API de Meta pasó el 75 % de uso.';
  if (sinObj.length) mensaje += '\nSin costo objetivo por lead: ' + sinObj.join(', ') + ' (solo reporto).';
  if (lineas.some(l => l.includes('(propuesta)'))) mensaje += '\nLas propuestas se aplican a mano en el Administrador de anuncios.';
}
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/&lt;(\/?)b&gt;/g, '<$1b>');
return [{ json: { simular: C.simular, frenado, errores, filas, lote_pausa_a: lote(pausas['marca-a']), lote_pausa_b: lote(pausas['marca-b']), mensaje: esc(mensaje).slice(0, 3900) } }];

// Revisa si Meta aceptó las pausas y deja una fila por decisión para la bitácora.
const D = $('Decidir').first().json;
const fallas = {};
for (const [marca, nodo] of [['marca-a', 'Pausar A'], ['marca-b', 'Pausar B']]) {
  let items = [];
  try { if ($(nodo).isExecuted) items = $(nodo).all().map(i => i.json || {}); } catch (e) {}
  items.forEach(x => {
    let body = {}; try { body = JSON.parse(x.body || '{}'); } catch (e) {}
    if (x.error || Number(x.code) !== 200 || body.error) fallas[marca] = ((x.error && x.error.message) || (body.error && body.error.message) || ('código ' + x.code));
  });
}
const filas = D.filas.map(f => (f.accion === 'pausar' && f.estado === 'aplicada' && fallas[f.marca]) ? Object.assign({}, f, { estado: 'error', detalle: (f.detalle + ' Meta no aceptó la pausa: ' + fallas[f.marca]).slice(0, 500) }) : f);
let mensaje = D.mensaje;
if (Object.keys(fallas).length) mensaje += '\n⚠️ Meta no aceptó alguna pausa: ' + Object.values(fallas).join(' · ').slice(0, 300).replace(/</g, '&lt;');
if (!filas.length && D.errores.length) throw new Error('No pude leer Meta Ads: ' + D.errores.join(' · ').slice(0, 400));
if (D.simular) return [];  // en simulación no se guarda nada; el resultado se ve en la ejecución
return filas.map((f, i) => ({ json: Object.assign({}, f, { mensaje: i === 0 ? mensaje : '' }) }));
